import pyomo.environ as pyo

DATA = {
    "techs": ["solar", "wind"],
    "cost": {"solar": 50, "wind": 60},
    "min_total": 1000,
    "solar_coeff": 3,
    "diff_max": 500,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.TECH = pyo.Set(initialize=d["techs"])

    model.capacity = pyo.Var(
        model.TECH,
        domain=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["cost"][t] * m.capacity[t] for t in m.TECH)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_capacity_rule(m):
        return sum(m.capacity[t] for t in m.TECH) >= d["min_total"]

    model.total_capacity = pyo.Constraint(rule=total_capacity_rule)

    def solar_wind_diff_rule(m):
        return (
            d["solar_coeff"] * m.capacity["solar"] - m.capacity["wind"]
            <= d["diff_max"]
        )

    model.solar_wind_diff = pyo.Constraint(rule=solar_wind_diff_rule)

    return model


